const { Pool } = require('pg');
const logger = require('../utils/logger');

// Database connection pool
let pool;
let poolShutdownRequested = false;
let poolCloseInProgress = false;

const normalizeQueryPreview = (text) => {
  const raw = text === undefined || text === null ? '' : String(text);
  return raw.replace(/\s+/g, ' ').trim().slice(0, 500);
};

/**
 * Initialize database connection pool
 */
function initializePool() {
  if (pool) {
    return pool;
  }

  const databaseUrl = process.env.DATABASE_URL;
  
  if (!databaseUrl) {
    logger.warn('DATABASE_URL not set, database features will be disabled');
    return null;
  }

  try {
    poolShutdownRequested = false;
    pool = new Pool({
      connectionString: databaseUrl,
      ssl: process.env.NODE_ENV === 'production' && !databaseUrl.includes('localhost') && !databaseUrl.includes('postgres:')
        ? { rejectUnauthorized: false }
        : false,
      max: parseInt(process.env.DB_POOL_MAX) || 20,
      idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT) || 30000,
      connectionTimeoutMillis: parseInt(process.env.DB_CONNECTION_TIMEOUT) || 2000,
      statement_timeout: parseInt(process.env.DB_STATEMENT_TIMEOUT_MS || '15000', 10) || 15000,
      query_timeout: parseInt(process.env.DB_QUERY_TIMEOUT_MS || '20000', 10) || 20000,
    });

    pool.on('connect', () => {
      logger.debug('New database client connected');
    });

    pool.on('error', (err) => {
      logger.error('Unexpected database error', { error: err.message });
    });

    logger.info('Database pool initialized successfully');
    return pool;
  } catch (error) {
    logger.error('Failed to initialize database pool', { error: error.message });
    return null;
  }
}

function isPoolShuttingDown() {
  if (poolCloseInProgress || poolShutdownRequested) {
    return true;
  }
  return Boolean(pool && (pool.ending === true || pool.ended === true));
}

/**
 * Get database pool instance
 */
function getPool() {
  if (!pool) {
    return initializePool();
  }
  return pool;
}

/**
 * Execute a query
 */
async function query(text, params) {
  const client = getPool();
  if (!client) {
    throw new Error('Database not initialized');
  }

  const start = Date.now();
  const queryPreview = normalizeQueryPreview(text);
  const paramCount = Array.isArray(params) ? params.length : 0;

  try {
    const result = await client.query(text, params);
    const duration = Date.now() - start;
    logger.debug('Executed query', {
      query: queryPreview,
      duration,
      rows: result.rowCount,
      paramCount,
    });
    return result;
  } catch (error) {
    const duration = Date.now() - start;
    const shutdownInProgress = isPoolShuttingDown();
    const message = String(error?.message || '');
    const isExpectedShutdownError = shutdownInProgress && (
      message.includes('Cannot use a pool after calling end on the pool')
      || message.includes('Connection terminated due to connection timeout')
    );

    const logPayload = {
      query: queryPreview,
      duration,
      paramCount,
      error: error?.message,
      code: error?.code,
      severity: error?.severity,
      detail: error?.detail,
      hint: error?.hint,
      where: error?.where,
      schema: error?.schema,
      table: error?.table,
      column: error?.column,
      constraint: error?.constraint,
      position: error?.position,
      internalPosition: error?.internalPosition,
      routine: error?.routine,
      stack: error?.stack,
      shutdownInProgress,
    };

    if (isExpectedShutdownError) {
      logger.debug('Query aborted during pool shutdown', logPayload);
    } else {
      logger.error('Query error', logPayload);
    }

    throw error;
  }
}

/**
 * Get a client from the pool for transactions
 */
async function getClient() {
  const client = getPool();
  if (!client) {
    throw new Error('Database not initialized');
  }
  return await client.connect();
}

/**
 * Test database connection
 */
async function testConnection() {
  try {
    const result = await query('SELECT NOW()');
    logger.info('Database connection test successful', { 
      timestamp: result.rows[0].now 
    });
    return true;
  } catch (error) {
    logger.error('Database connection test failed', { 
      error: error.message,
      stack: error.stack,
      code: error.code 
    });
    return false;
  }
}

/**
 * Close database pool
 */
async function closePool() {
  if (!pool) {
    return;
  }

  if (poolCloseInProgress) {
    return;
  }

  poolShutdownRequested = true;
  poolCloseInProgress = true;

  try {
    await pool.end();
    logger.info('Database pool closed');
  } finally {
    pool = null;
    poolCloseInProgress = false;
  }
}

module.exports = {
  initializePool,
  getPool,
  query,
  getClient,
  testConnection,
  isPoolShuttingDown,
  closePool,
};
